// Default brand logo, used when the host provides no `meta.logo`: the Vinx
// lynx — a flat, badge-style mark (copper-amber disc, cream lynx head, black
// ear tufts). Cut from the painted logo.png at the repo root (watermark
// removed, corners made transparent along the disc), downscaled to 512 px
// so a 56 px welcome mark stays sharp on 3x displays; inlined as a base64
// PNG data URI so it survives both the library build (non-CSS assets fold
// into styles.css) and the SPA build. The favicons in the two index.html
// files are the same disc at 64 px.
export const VINX_LOGO =
  "data:image/png;base64,"
